const svg=document.getElementById("overlay"),viewport=document.getElementById("mapViewport"),stage=document.getElementById("mapStage"),tip=document.getElementById("tooltip"),search=document.getElementById("search"),suggestions=document.getElementById("suggestions");
let scale=.58,tx=0,ty=0,dragging=false,startX=0,startY=0,startTx=0,startTy=0,selected=null;
function mapLink(l){return "https://www.google.com/maps/search/?api=1&query="+encodeURIComponent(`${l.address}, ${l.city}, ${l.state} ${l.zip}`)}
function drawLots(){const NS="http://www.w3.org/2000/svg";lots.forEach(l=>{const p=document.createElementNS(NS,"polygon");p.setAttribute("points",l.points.map(q=>q.join(",")).join(" "));p.classList.add("lot-hit");p.dataset.lot=l.lot;p.setAttribute("tabindex","0");p.setAttribute("aria-label",`Lot ${l.lot}, ${l.address}`);p.addEventListener("mouseenter",()=>showTip(l,p));p.addEventListener("click",e=>{e.stopPropagation();selectLot(l,p,false)});p.addEventListener("focus",()=>showTip(l,p));svg.appendChild(p)})}
function apply(){stage.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`}
function fit(){const r=viewport.getBoundingClientRect();scale=Math.min(r.width/1064,r.height/1436)*.96;tx=(r.width-1064*scale)/2;ty=(r.height-1436*scale)/2;apply()}
function zoom(f,cx=viewport.clientWidth/2,cy=viewport.clientHeight/2){const old=scale;scale=Math.max(.25,Math.min(4,scale*f));tx=cx-(cx-tx)*(scale/old);ty=cy-(cy-ty)*(scale/old);apply()}
function showTip(l,e){document.querySelectorAll(".lot-hit.selected").forEach(x=>x.classList.remove("selected"));e.classList.add("selected");selected=e;tip.innerHTML=`<button class="close" aria-label="Close">×</button><h3>Lot ${l.lot}</h3><div><strong>Address:</strong> <a target="_blank" rel="noopener" href="${mapLink(l)}">${l.address}</a></div><div><strong>City, State, Zip:</strong> ${l.city}, ${l.state} ${l.zip}</div>`;tip.style.display="block";tip.querySelector(".close").addEventListener("click",hideTip);const x=tx+l.cx*scale,y=ty+l.cy*scale;tip.style.left=Math.max(8,Math.min(viewport.clientWidth-340,x+18))+"px";tip.style.top=Math.max(8,Math.min(viewport.clientHeight-145,y-60))+"px"}
function hideTip(){tip.style.display="none";if(selected)selected.classList.remove("selected");selected=null}
function selectLot(l,e,fromSearch){document.querySelectorAll(".search-result").forEach(x=>x.classList.remove("search-result"));if(fromSearch)e.classList.add("search-result");scale=Math.max(scale,1.15);tx=viewport.clientWidth/2-l.cx*scale;ty=viewport.clientHeight/2-l.cy*scale;apply();showTip(l,e)}
function findMatches(q){q=q.trim().toLowerCase().replace(/^lot\s*/,"");if(!q)return[];return lots.filter(l=>String(l.lot)===q||`${l.address} ${l.city} ${l.state} ${l.zip}`.toLowerCase().includes(q)).slice(0,12)}
function renderSuggestions(){const m=findMatches(search.value);suggestions.innerHTML="";if(!search.value.trim()||!m.length){suggestions.style.display="none";return}m.forEach(l=>{const b=document.createElement("button");b.type="button";b.textContent=`Lot ${l.lot} — ${l.address}`;b.addEventListener("click",()=>{search.value=`Lot ${l.lot} — ${l.address}`;suggestions.style.display="none";go(l)});suggestions.appendChild(b)});suggestions.style.display="block"}
function go(l){selectLot(l,svg.querySelector(`[data-lot="${l.lot}"]`),true)}function doSearch(){const m=findMatches(search.value);if(m.length)go(m[0]);else alert("No matching lot or address was found.")}
search.addEventListener("input",renderSuggestions);search.addEventListener("keydown",e=>{if(e.key==="Enter"){suggestions.style.display="none";doSearch()}});document.getElementById("searchBtn").addEventListener("click",doSearch);document.getElementById("zoomIn").addEventListener("click",()=>zoom(1.25));document.getElementById("zoomOut").addEventListener("click",()=>zoom(.8));document.getElementById("reset").addEventListener("click",()=>{hideTip();document.querySelectorAll(".search-result").forEach(x=>x.classList.remove("search-result"));fit()});
viewport.addEventListener("pointerdown",e=>{if(e.target.classList.contains("lot-hit"))return;dragging=true;viewport.classList.add("dragging");startX=e.clientX;startY=e.clientY;startTx=tx;startTy=ty;viewport.setPointerCapture(e.pointerId)});viewport.addEventListener("pointermove",e=>{if(!dragging)return;tx=startTx+e.clientX-startX;ty=startTy+e.clientY-startY;apply()});viewport.addEventListener("pointerup",()=>{dragging=false;viewport.classList.remove("dragging")});viewport.addEventListener("wheel",e=>{e.preventDefault();const r=viewport.getBoundingClientRect();zoom(e.deltaY<0?1.12:.89,e.clientX-r.left,e.clientY-r.top)},{passive:false});viewport.addEventListener("click",e=>{if(e.target===viewport||e.target===stage||e.target===svg)hideTip()});window.addEventListener("resize",fit);
drawLots();fit();
